import{Et as e,Gt as t,Tt as n,n as r}from"./chunks/framework.D88M5COo.js";var i=JSON.parse(`{"title":"Zotero 插件开发指南","description":"插件开发指南：待完善，前托管于语雀的开发者文档主要针对 Zotero 6，鉴于插件在 Zotero 7 相对 Zotero 6 变动较大，因此插件开发者文档需要重写。","frontmatter":{"title":"插件开发指南","date":"2023-04-20T10:06:59.000Z","updated":"2023-07-20T16:51:54.000Z","authors":["windingwind"],"description":"插件开发指南：待完善，前托管于语雀的开发者文档主要针对 Zotero 6，鉴于插件在 Zotero 7 相对 Zotero 6 变动较大，因此插件开发者文档需要重写。"},"headers":[],"relativePath":"plugin-dev-guide/index.md","filePath":"wiki/plugin-dev-guide/index.md","git":{"contributors":[{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"}],"changelog":[{"hash":"6f05a4d945722a3501035e323c1cbf15ec191a3c","time":1722064170000,"message":"维护：修改页面增补作者格式 (<a href=\\"https://github.com/zotero-chinese/wiki/issues/240\\" target=\\"_blank\\" rel=\\"noreferrer\\">#240</a>)","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/6f05a4d945722a3501035e323c1cbf15ec191a3c"},{"hash":"43e9d0ffbce770c9175de4c929f12fa5252a3d66","time":1714804981000,"message":"refactor: migrate SSG to VitePress, migrate website to zotero-chinese/website repo (<a href=\\"https://github.com/zotero-chinese/wiki/issues/172\\" target=\\"_blank\\" rel=\\"noreferrer\\">#172</a>)","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/43e9d0ffbce770c9175de4c929f12fa5252a3d66"},{"hash":"ba1e2f057d4b41b2917d9dba2bf90f3f058929c1","time":1706850681000,"message":"同步未过时的插件开发者文档 (<a href=\\"https://github.com/zotero-chinese/wiki/issues/125\\" target=\\"_blank\\" rel=\\"noreferrer\\">#125</a>)","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/ba1e2f057d4b41b2917d9dba2bf90f3f058929c1"},{"hash":"1b960e2fbce8a8ed526dcb21b64f677d43da4307","time":1695222840000,"message":"将 about/ 内容移出子目录 新增贡献者列表；对未完成文档添加待办标记；完善 csl 侧边栏配置","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/1b960e2fbce8a8ed526dcb21b64f677d43da4307"},{"hash":"6486b76f76944ce53aa4509e6aec30fc53361f9e","time":1689844264000,"message":"tweak, stage update","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/6486b76f76944ce53aa4509e6aec30fc53361f9e"},{"hash":"74dd2f5c275f03d178dcdbad8bf40be341c8c232","time":1681956581000,"message":"add: directory structure","author":{"name":"Northword","avatar":"https://github.com/northword.png","url":"https://github.com/northword"},"commitUrl":"https://github.com/zotero-chinese/wiki/commit/74dd2f5c275f03d178dcdbad8bf40be341c8c232"}]}}`),a={name:`plugin-dev-guide/index.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="插件开发指南" tabindex="-1">插件开发指南 <a class="header-anchor" href="#插件开发指南" aria-label="Permalink to “插件开发指南”">​</a></h1><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">提示</p><p>待完善，前托管于语雀的开发者文档主要针对 Zotero 6，鉴于插件在 Zotero 7 相对 Zotero 6 变动较大，因此插件开发者文档需要重写。</p></div><p>本文档所述内容仅适用于 Zotero 7 插件开发，Zotero 6 插件开发文档请参阅 <a href="https://zotero.yuque.com/staff-gkhviy/developer/" target="_blank" rel="noreferrer">Zotero 6 插件开发文档</a>。</p><h2 id="前置基础知识" tabindex="-1">前置基础知识 <a class="header-anchor" href="#前置基础知识" aria-label="Permalink to “前置基础知识”">​</a></h2><p>Zotero 插件遵循 Firefox 插件的要求。此处列举了编写插件的基础知识。并非所有知识都需要掌握，只需要在遇到问题时能通过查阅文档找到解决方法即可。</p><h3 id="firefox-插件" tabindex="-1">Firefox 插件 <a class="header-anchor" href="#firefox-插件" aria-label="Permalink to “Firefox 插件”">​</a></h3><p><a href="http://mb.eschew.org/intro" target="_blank" rel="noreferrer">Introduction: Welcome to Software Development the Mozilla Way</a></p><p><a href="https://developer.mozilla.org/zh-CN/docs/Mozilla/Add-ons/WebExtensions" target="_blank" rel="noreferrer">Web 浏览器扩展</a></p><h3 id="html-xul" tabindex="-1">HTML / XUL <a class="header-anchor" href="#html-xul" aria-label="Permalink to “HTML / XUL”">​</a></h3><p>关于 HTML，可参考网上的任意教程，只需理解基本的树结构，大致清楚元素类型与通用属性即可。 参考文档：<a href="https://www.runoob.com/html/html-tutorial.html" target="_blank" rel="noreferrer">HTML 教程 | 菜鸟教程</a> 关于 XUL，在了解 HTML 的基础上只需大概浏览文档即可。在使用时可随时查阅文档。 参考文档：<a href="https://docs.huihoo.com/xul/" target="_blank" rel="noreferrer">Huihoo - XML User Interface Language (XUL)</a>，<a href="https://udn.realityripple.com/docs/Archive/Add-ons/Overlay_Extensions/XUL_School" target="_blank" rel="noreferrer">XUL School Tutorial - Archive of obsolete content</a></p><h3 id="javascript-typescript" tabindex="-1">JavaScript / TypeScript <a class="header-anchor" href="#javascript-typescript" aria-label="Permalink to “JavaScript / TypeScript”">​</a></h3><p>如果对其他编程语言有了解，上手 JavaScript 很快，看一下基本语法即可。 参考文档：<a href="https://www.w3school.com.cn/js/index.asp" target="_blank" rel="noreferrer">JavaScript 教程</a></p><p>（非必需）也可以直接学习 TypeScript，它是 JS 的超集，提供了更多特性，并对习惯于 C++/JAVA 等强类型语言的开发者而言更加熟悉。第二章将要介绍的的 Zotero 插件框架支持 TS。 参考文档：<a href="https://www.tslang.cn/" target="_blank" rel="noreferrer">TypeScript 中文网 · TypeScript——JavaScript 的超集</a></p><h3 id="git" tabindex="-1">Git <a class="header-anchor" href="#git" aria-label="Permalink to “Git”">​</a></h3><p>Git 是版本管理的常用工具。 参考文档：<a href="https://www.runoob.com/git/git-tutorial.html" target="_blank" rel="noreferrer">Git 教程 | 菜鸟教程</a></p><h3 id="zotero-官方资料" tabindex="-1">Zotero 官方资料 <a class="header-anchor" href="#zotero-官方资料" aria-label="Permalink to “Zotero 官方资料”">​</a></h3><p>Zoero 文档（部分过时或不全）：<a href="https://www.zotero.org/support/" target="_blank" rel="noreferrer">start [Zotero Documentation]</a> Zotero 社区：<a href="https://forums.zotero.org/discussions" target="_blank" rel="noreferrer">Recent Discussions</a> Zotero 贡献文档：<a href="https://www.zotero.org/getinvolved/" target="_blank" rel="noreferrer">Zotero | Get Involved</a> Zotero 开发者群组：<a href="https://groups.google.com/g/zotero-dev" target="_blank" rel="noreferrer">https://groups.google.com/g/zotero-dev</a> 社区维护的 Zotero Types 接口类型定义包：<a href="https://github.com/windingwind/zotero-types" target="_blank" rel="noreferrer">windingwind / Zotero-types</a> <a href="https://www.npmjs.com/package/zotero-types" target="_blank" rel="noreferrer">Zotero-types</a></p><h2 id="本文档的结构" tabindex="-1">本文档的结构 <a class="header-anchor" href="#本文档的结构" aria-label="Permalink to “本文档的结构”">​</a></h2><blockquote><p>todo</p></blockquote>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};